; margin: 0px; padding: 0px; position: relative; text-align: inherit; white-space: inherit; overflow-wrap: break-word; min-width: 0px;\"><span class=\"css-1jxf684 r-bcqeeo r-1ttztb7 r-qvutc0 r-poiln3 r-b88u0q r-1x3r274\" style=\"border: 0px solid black; box-sizing: border-box; display: inline; font-style: inherit; font-variant: inherit; font-weight: bold; font-stretch: inherit; font-size: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; list-style: none; margin: 0px; padding: 0px; position: relative; text-align: inherit; white-space: inherit; overflow-wrap: break-word; min-width: 0px;\"><span class=\"css-1jxf684 r-bcqeeo r-1ttztb7 r-qvutc0 r-poiln3\" style=\"border: 0px solid black; box-sizing: border-box; display: inline; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; list-style: none; margin: 0px; padding: 0px; position: relative; text-align: inherit; white-space: inherit; overflow-wrap: break-word; min-width: 0px;\"><span class=\"css-1jxf684 r-bcqeeo r-1ttztb7 r-qvutc0 r-poiln3 r-1x3r274\" style=\"border: 0px solid black; box-sizing: border-box; display: inline; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; list-style: none; margin: 0px; padding: 0px; position: relative; text-align: inherit; white-space: inherit; overflow-wrap: break-word; min-width: 0px;\"><span class=\"css-1jxf684 r-bcqeeo r-1ttztb7 r-qvutc0 r-poiln3\" style=\"border: 0px solid black; box-sizing: border-box; display: